package main

import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string              // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string               // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string             // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec
var loanFile *os.File
var loanScanner *bufio.Scanner

func main() {
	MainPara()
}

// MAIN-PARA
func MainPara() {
	OpenLoanFile()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	CloseLoanFile()
	SummaryPara()
}

// READ-PARA
func ReadPara() {
	if loanScanner.Scan() {
		line := loanScanner.Text()
		if len(line) < 21 {
			line = line + strings.Repeat(" ", 21-len(line))
		} else if len(line) > 21 {
			line = line[:21]
		}
		lrAcct := line[0:6]
		lrPrincipalStr := line[6:15]
		lrRateStr := line[15:19]
		lrYearsStr := line[19:21]

		loanRec.LrAcct = lrAcct
		loanRec.LrPrincipal = parseDecimalField(lrPrincipalStr, 2)
		loanRec.LrRate = parseDecimalField(lrRateStr, 2)
		loanRec.LrYears = parseIntField(lrYearsStr)
	} else {
		if err := loanScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

// PROCESS-PARA
func ProcessPara() {
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate)
	raw = raw.Mul(decimal.NewFromInt(loanRec.LrYears))
	raw = raw.Shift(-2)
	WsInterest = roundHalfAway(raw, 2)
	WsInterest = applyPICOverflow(WsInterest, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = applyPICOverflow(WsTotal, 11, 2)

	WsCount++
	if WsCount >= 100000 {
		WsCount %= 100000
	}

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	ReadPara()
}

// SUMMARY-PARA
func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func OpenLoanFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	loanFile = f
	loanScanner = bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	loanScanner.Buffer(buf, maxCap)
}

func CloseLoanFile() {
	if loanFile != nil {
		loanFile.Close()
	}
}

func parseDecimalField(s string, scale int) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	var digits strings.Builder
	sign := 1
	for i, ch := range trimmed {
		if ch == '-' && i == 0 {
			sign = -1
			continue
		}
		if ch == '+' && i == 0 {
			continue
		}
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	dStr := digits.String()
	if dStr == "" {
		return decimal.Zero
	}
	bi, ok := new(big.Int).SetString(dStr, 10)
	if !ok {
		return decimal.Zero
	}
	d := decimal.NewFromBigInt(bi, int32(-scale))
	if sign == -1 {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	var digits strings.Builder
	for _, ch := range trimmed {
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	dStr := digits.String()
	if dStr == "" {
		return 0
	}
	v, err := strconv.ParseInt(dStr, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func roundHalfAway(d decimal.Decimal, places int32) decimal.Decimal {
	shifted := d.Shift(places)
	intPart := shifted.Truncate(0)
	frac := shifted.Sub(intPart)
	absFrac := frac.Abs()
	half := decimal.NewFromInt(5).Shift(-1) // 0.5
	if absFrac.Cmp(half) < 0 {
		return intPart.Shift(-places)
	}
	if shifted.Sign() >= 0 {
		intPart = intPart.Add(decimal.NewFromInt(1))
	} else {
		intPart = intPart.Sub(decimal.NewFromInt(1))
	}
	return intPart.Shift(-places)
}

func applyPICOverflow(v decimal.Decimal, intDigits, scale int) decimal.Decimal {
	intPart := v.Truncate(0)
	pow := decimal.New(1, int32(intDigits))
	if intPart.Abs().Cmp(pow) >= 0 {
		absStr := intPart.Abs().StringFixed(0)
		biAbs := new(big.Int)
		biAbs.SetString(absStr, 10)
		powBi := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(intDigits)), nil)
		remBi := new(big.Int).Mod(biAbs, powBi)
		remDec := decimal.NewFromBigInt(remBi, 0)
		if intPart.Sign() < 0 {
			remDec = remDec.Neg()
		}
		frac := v.Sub(intPart)
		return remDec.Add(frac)
	}
	return v
}

func formatEdited(v decimal.Decimal, picture string) string {
	parts := strings.Split(picture, ".")
	intPic := parts[0]
	fracPic := ""
	if len(parts) > 1 {
		fracPic = parts[1]
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	fracDigits := len(fracPic)

	vQuant := v.Truncate(int32(fracDigits))
	vFinal := applyPICOverflow(vQuant, intDigits, fracDigits)

	isNegative := vFinal.Sign() < 0
	absVal := vFinal.Abs()

	intPart := absVal.Truncate(0)
	intStr := intPart.StringFixed(0)
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}

	picRunes := []rune(intPic)
	outRunes := make([]rune, len(picRunes))
	copy(outRunes, picRunes)

	placeholderPos := []int{}
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			placeholderPos = append(placeholderPos, i)
		}
	}

	firstSigIdx := intDigits
	for i, ch := range intStr {
		if ch != '0' {
			firstSigIdx = i
			break
		}
	}

	for i, pos := range placeholderPos {
		typ := picRunes[pos]
		digitCh := rune(intStr[i])
		if typ == 'Z' {
			if i < firstSigIdx {
				outRunes[pos] = ' '
			} else {
				outRunes[pos] = digitCh
			}
		} else {
			outRunes[pos] = digitCh
		}
	}

	firstSigPicPos := len(picRunes)
	if firstSigIdx < intDigits {
		firstSigPicPos = placeholderPos[firstSigIdx]
	}
	for i, ch := range picRunes {
		if ch == ',' {
			if i < firstSigPicPos {
				outRunes[i] = ' '
			} else {
				outRunes[i] = ','
			}
		}
	}
	intFormatted := string(outRunes)

	fracStr := ""
	if fracDigits > 0 {
		fracDec := absVal.Sub(intPart)
		powDec := decimal.New(1, int32(fracDigits))
		fracIntDec := fracDec.Mul(powDec).Truncate(0)
		fracIntStr := fracIntDec.StringFixed(0)
		if len(fracIntStr) < fracDigits {
			fracStr = strings.Repeat("0", fracDigits-len(fracIntStr)) + fracIntStr
		} else {
			if len(fracIntStr) > fracDigits {
				fracStr = fracIntStr[len(fracIntStr)-fracDigits:]
			} else {
				fracStr = fracIntStr
			}
		}
		_ = isNegative
		return intFormatted + "." + fracStr
	}
	return intFormatted
}
